function utf8Bytes(s){
  var out=[]; s=String(s==null?'':s);
  for(var i=0;i<s.length;i++){
    var c=s.charCodeAt(i);
    if(c<0x80) out.push(c);
    else if(c<0x800) out.push(0xC0|(c>>6),0x80|(c&63));
    else if(c<0xD800||c>=0xE000) out.push(0xE0|(c>>12),0x80|((c>>6)&63),0x80|(c&63));
    else { i++; var c2=s.charCodeAt(i); var cp=0x10000+((c&0x3FF)<<10)+(c2&0x3FF);
      out.push(0xF0|(cp>>18),0x80|((cp>>12)&63),0x80|((cp>>6)&63),0x80|(cp&63)); }
  }
  return out;
}
var B64='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function b64encodeBytes(bytes){
  var out='', i;
  for(i=0;i+2<bytes.length;i+=3){
    var n=(bytes[i]<<16)|(bytes[i+1]<<8)|bytes[i+2];
    out+=B64[(n>>18)&63]+B64[(n>>12)&63]+B64[(n>>6)&63]+B64[n&63];
  }
  var rem=bytes.length-i;
  if(rem===1){ var a=bytes[i]<<16; out+=B64[(a>>18)&63]+B64[(a>>12)&63]+'=='; }
  else if(rem===2){ var b=(bytes[i]<<16)|(bytes[i+1]<<8); out+=B64[(b>>18)&63]+B64[(b>>12)&63]+B64[(b>>6)&63]+'='; }
  return out;
}
function b64(s){ return b64encodeBytes(utf8Bytes(s==null?'':s)); }

function sanitizeName(s){
  var t=String(s==null?'':s).toLowerCase().trim();
  t=t.replace(/[^a-z0-9.\-]/g,'-');
  t=t.replace(/-+/g,'-').replace(/^-+/,'').replace(/-+$/,'');
  t=t.slice(0,63);
  return t;
}
function isValidName(s){ return /^[a-z0-9]([-a-z0-9]*[a-z0-9])?$/.test(String(s==null?'':s)) && String(s).length<=63; }

function indent(lines, pad){ return lines.map(function(l){ return l==='' ? '' : pad+l; }).join('\n'); }

function genDeployment(o){
  o=o||{};
  var name=sanitizeName(o.name||'app');
  var replicas=o.replicas==null?1:parseInt(o.replicas,10);
  if(!isFinite(replicas)||replicas<0) replicas=1;
  var img=o.image||'nginx:latest';
  var port=o.port==null?80:parseInt(o.port,10);
  if(!isFinite(port)||port<1||port>65535) port=80;
  var cpu=o.cpu||'100m', mem=o.mem||'128Mi', ns=o.namespace||'default';
  var L=[];
  L.push('apiVersion: apps/v1');
  L.push('kind: Deployment');
  L.push('metadata:');
  L.push('  name: '+name);
  L.push('  namespace: '+ns);
  L.push('spec:');
  L.push('  replicas: '+replicas);
  L.push('  selector:');
  L.push('    matchLabels:');
  L.push('      app: '+name);
  L.push('  template:');
  L.push('    metadata:');
  L.push('      labels:');
  L.push('        app: '+name);
  L.push('    spec:');
  L.push('      containers:');
  L.push('      - name: '+name);
  L.push('        image: '+img);
  if(o.imagePullPolicy) L.push('        imagePullPolicy: '+o.imagePullPolicy);
  L.push('        ports:');
  L.push('        - containerPort: '+port);
  L.push('        resources:');
  L.push('          requests:');
  L.push('            cpu: '+cpu);
  L.push('            memory: '+mem);
  if(o.env && o.env.length){
    L.push('        env:');
    o.env.forEach(function(e){ L.push('        - name: '+e.name+'');
      if(e.value!=null) L.push('          value: '+JSON.stringify(String(e.value))); });
  }
  return L.join('\n');
}

function genService(o){
  o=o||{};
  var name=sanitizeName(o.name||'app');
  var port=o.port==null?80:parseInt(o.port,10);
  var targetPort=o.targetPort==null?port:parseInt(o.targetPort,10);
  var ns=o.namespace||'default', typ=o.type||'ClusterIP';
  var L=[];
  L.push('apiVersion: v1');
  L.push('kind: Service');
  L.push('metadata:');
  L.push('  name: '+name);
  L.push('  namespace: '+ns);
  L.push('spec:');
  L.push('  type: '+typ);
  L.push('  selector:');
  L.push('    app: '+name);
  L.push('  ports:');
  L.push('  - port: '+port);
  L.push('    targetPort: '+targetPort);
  L.push('    protocol: TCP');
  return L.join('\n');
}

function genConfigMap(o){
  o=o||{};
  var name=sanitizeName(o.name||'config');
  var ns=o.namespace||'default';
  var L=[];
  L.push('apiVersion: v1');
  L.push('kind: ConfigMap');
  L.push('metadata:');
  L.push('  name: '+name);
  L.push('  namespace: '+ns);
  L.push('data:');
  var keys=o.data||{};
  Object.keys(keys).forEach(function(k){ L.push('  '+k+': '+JSON.stringify(String(keys[k]))); });
  if(!Object.keys(keys).length) L.push('  example: "value"');
  return L.join('\n');
}

function genSecret(o){
  o=o||{};
  var name=sanitizeName(o.name||'secret');
  var ns=o.namespace||'default';
  var L=[];
  L.push('apiVersion: v1');
  L.push('kind: Secret');
  L.push('metadata:');
  L.push('  name: '+name);
  L.push('  namespace: '+ns);
  L.push('type: Opaque');
  L.push('data:');
  var keys=o.data||{};
  Object.keys(keys).forEach(function(k){ L.push('  '+k+': '+b64(keys[k])); });
  if(!Object.keys(keys).length) L.push('  token: '+b64('change-me'));
  return L.join('\n');
}

function genIngress(o){
  o=o||{};
  var name=sanitizeName(o.name||'ingress');
  var ns=o.namespace||'default';
  var host=o.host||'example.com';
  var svc=o.service||sanitizeName(o.name||'app');
  var port=o.port==null?80:parseInt(o.port,10);
  var L=[];
  L.push('apiVersion: networking.k8s.io/v1');
  L.push('kind: Ingress');
  L.push('metadata:');
  L.push('  name: '+name);
  L.push('  namespace: '+ns);
  L.push('spec:');
  L.push('  rules:');
  L.push('  - host: '+host);
  L.push('    http:');
  L.push('      paths:');
  L.push('      - path: /');
  L.push('        pathType: Prefix');
  L.push('        backend:');
  L.push('          service:');
  L.push('            name: '+svc);
  L.push('            port:');
  L.push('              number: '+port);
  return L.join('\n');
}

function genHPA(o){
  o=o||{};
  var name=sanitizeName(o.name||'app');
  var ns=o.namespace||'default';
  var min=o.minReplicas==null?2:parseInt(o.minReplicas,10);
  var max=o.maxReplicas==null?10:parseInt(o.maxReplicas,10);
  var cpu=o.cpuUtilization==null?80:parseInt(o.cpuUtilization,10);
  var L=[];
  L.push('apiVersion: autoscaling/v2');
  L.push('kind: HorizontalPodAutoscaler');
  L.push('metadata:');
  L.push('  name: '+name);
  L.push('  namespace: '+ns);
  L.push('spec:');
  L.push('  scaleTargetRef:');
  L.push('    apiVersion: apps/v1');
  L.push('    kind: Deployment');
  L.push('    name: '+name);
  L.push('  minReplicas: '+min);
  L.push('  maxReplicas: '+max);
  L.push('  metrics:');
  L.push('  - type: Resource');
  L.push('    resource:');
  L.push('      name: cpu');
  L.push('      target:');
  L.push('        type: Utilization');
  L.push('        averageUtilization: '+cpu);
  return L.join('\n');
}

function genPVC(o){
  o=o||{};
  var name=sanitizeName(o.name||'data');
  var ns=o.namespace||'default';
  var size=o.size||'1Gi';
  var L=[];
  L.push('apiVersion: v1');
  L.push('kind: PersistentVolumeClaim');
  L.push('metadata:');
  L.push('  name: '+name);
  L.push('  namespace: '+ns);
  L.push('spec:');
  L.push('  accessModes:');
  L.push('    - ReadWriteOnce');
  L.push('  resources:');
  L.push('    requests:');
  L.push('      storage: '+size);
  return L.join('\n');
}

var KIND_BUILDERS = {
  deployment: genDeployment, service: genService, configmap: genConfigMap,
  secret: genSecret, ingress: genIngress, hpa: genHPA, pvc: genPVC
};

function buildKind(opt){
  opt=opt||{};
  var kind=String(opt.kind||'').toLowerCase();
  var fn=KIND_BUILDERS[kind];
  if(!fn) return { error:'未知资源类型: '+kind, value:'' };
  return { error:null, value: fn(opt), kind: kind };
}

function lintSpec(opt){
  opt=opt||{};
  var issues=[];
  var raw=opt.name||'app';
  if(!isValidName(raw)){
    if(sanitizeName(raw)==='' || !isValidName(sanitizeName(raw)))
      issues.push({level:'bad', msg:'名称 "'+raw+'" 不符合 RFC 1123（小写字母数字、-、.、≤63 字符）'});
    else
      issues.push({level:'warn', msg:'名称 "'+raw+'" 含非法字符，将按 RFC 1123 规范化为 "'+sanitizeName(raw)+'"'});
  }
  if(opt.image===undefined || opt.image==='') {
    if(String(opt.kind).toLowerCase()!=='configmap' && String(opt.kind).toLowerCase()!=='secret'
       && String(opt.kind).toLowerCase()!=='pvc' && String(opt.kind).toLowerCase()!=='hpa'
       && String(opt.kind).toLowerCase()!=='ingress')
      issues.push({level:'bad', msg:'缺少容器镜像 image'});
  } else if(/:/.test(opt.image)===false && String(opt.kind).toLowerCase()!=='configmap' && String(opt.kind).toLowerCase()!=='secret')
    issues.push({level:'warn', msg:'镜像 "'+opt.image+'" 未指定 tag，将使用 latest'});
  var p=opt.port==null?80:parseInt(opt.port,10);
  if(opt.port!=null && (!isFinite(p)||p<1||p>65535))
    issues.push({level:'bad', msg:'端口 '+opt.port+' 超出 1–65535 范围'});
  if(opt.kind==='hpa'){
    var mn=parseInt(opt.minReplicas,10), mx=parseInt(opt.maxReplicas,10);
    if(isFinite(mn)&&isFinite(mx)&&mn>mx) issues.push({level:'bad', msg:'HPA minReplicas 不能大于 maxReplicas'});
  }
  var score=100; issues.forEach(function(i){ score-=(i.level==='bad'?20:8); });
  return { issues:issues, score:Math.max(0,score) };
}

function runtimeYaml(specs){
  var out=[], errs=[];
  (specs||[]).forEach(function(s){
    var r=buildKind(s);
    if(r.error){ errs.push(r.error); return; }
    out.push(r.value);
  });
  return { value: out.join('\n---\n'), errors: errs };
}

var K8sForgePure = {
  sanitizeName: sanitizeName, isValidName: isValidName, b64: b64,
  genDeployment: genDeployment, genService: genService, genConfigMap: genConfigMap,
  genSecret: genSecret, genIngress: genIngress, genHPA: genHPA, genPVC: genPVC,
  buildKind: buildKind, lintSpec: lintSpec, runtimeYaml: runtimeYaml,
  KIND_BUILDERS: KIND_BUILDERS
};
if (typeof module !== 'undefined' && module.exports) module.exports = K8sForgePure;
if (typeof window !== 'undefined') window.K8sForgePure = K8sForgePure;
